import sys

def main():
    input = sys.stdin.read
    data = input().split()

    # Convert input to a 3x3 grid
    grid = [[int(data[i*3 + j]) for j in range(3)] for i in range(3)]

    # Check row differences
    for i in range(3):
        diff = grid[i][1] - grid[i][0]
        if grid[i][2] - grid[i][1] != diff:
            print("No")
            return

    # Check column differences
    for j in range(3):
        diff = grid[1][j] - grid[0][j]
        if grid[2][j] - grid[1][j] != diff:
            print("No")
            return

    # Verify the first element of each row can be expressed as the sum of a constant and the first element of the corresponding column
    a1 = grid[0][0]
    b1 = grid[0][1] - a1
    for i in range(3):
        if grid[i][0] != a1 + (grid[0][0] - a1):
            print("No")
            return
        for j in range(3):
            if grid[i][j] != (a1 + (grid[i][0] - a1)) + (b1 + (grid[0][j] - b1)):
                print("No")
                return

    print("Yes")

